    public function run(): void
    {
        $data = [
            '‘আনারস’ এবং ‘চাবি’ শব্দ দুটি বাংলা ভাষা গ্রহণ করেছে-' => '<strong>পর্তুগিজ শব্দ</strong>: পর্তুগিজরা ভারতবর্ষে বাণিজ্য ও ধর্মপ্রচারের উদ্দেশ্যে এলে তাদের ভাষার বহু শব্দ বাংলায় প্রবেশ করে। যেমন: আনারস, চাবি, আলমারি, পাউরুটি, পেঁপে, তোয়ালে, পাদ্রি, গির্জা ইত্যাদি।',
            'শুদ্ধ বানান কোনটি?' => '<strong>মুমূর্ষু</strong>: সংস্কৃত ‘মৃ’ ধাতু নিষ্পন্ন এ শব্দটির সঠিক বানান ‘মুমূর্ষু’ (হ্রস্ব-উ + দীর্ঘ-ঊ + হ্রস্ব-উ)। এর অর্থ—মৃত্যুর কাছাকাছি উপনীত বা মৃত্যুমুখী ব্যক্তি।',
            'শুদ্ধ বাক্য কোনটি?' => '<strong>দুর্বলতাবশত অনাথা বসে পড়ল</strong>: ‘অনাথ’ শব্দের সঠিক স্ত্রীলিঙ্গ রূপ ‘অনাথা’ (‘অনাথিনী’ ব্যাকরণগতভাবে অশুদ্ধ)। এছাড়া ‘দুর্বলতাবশত’ বানানে শেষে বিসর্গ (ঃ) হবে না।',
            'গুরুচণ্ডালী দোষমুক্ত কোনটি?' => '<strong>শবদাহ</strong>: তৎসম (সংস্কৃত) শব্দের সাথে দেশি শব্দের অনুপযুক্ত মিশ্রণকে গুরুচণ্ডালী দোষ বলে। ‘শব’ (তৎসম) এর সাথে তৎসম ‘দাহ’ মিলে ‘শবদাহ’ শুদ্ধ। কিন্তু তৎসম ‘শব’-এর সাথে দেশি ‘পোড়া’ মিশিয়ে ‘শবপোড়া’ বা দেশি ‘মড়া’-র সাথে ‘দাহ’ মিশিয়ে ‘মড়াদাহ’ গুরুচণ্ডালী দোষযুক্ত।',
            '‘কবর’ নাটকটির লেখক-' => '<strong>মুনীর চৌধুরী</strong>: ১৯৫২ সালের ভাষা আন্দোলনের পটভূমিতে রচিত কালজয়ী প্রতীকী একাঙ্কিকা ‘কবর’। লেখক ও বুদ্ধিজীবী মুনীর চৌধুরী ১৯৫৩ সালে ঢাকা কেন্দ্রীয় কারাগারে রাজবন্দি থাকা অবস্থায় এটি রচনা করেছিলেন।',
            'বাংলায় কোরআন শরীফের প্রথম অনুবাদক কে?' => '<strong>ভাই গিরিশচন্দ্র সেন</strong>: ব্রাহ্মধর্ম প্রচারক ও গবেষক গিরিশচন্দ্র সেন ১৮৮১ থেকে ১৮৮৬ সালের মধ্যে পবিত্র কোরআন শরীফের পূর্ণাঙ্গ বাংলা অনুবাদ সম্পন্ন করেন।',
            '‘রত্নাকর’ শব্দটির সন্ধি-বিচ্ছেদ-' => '<strong>রত্ন + আকর</strong>: এটি স্বরসন্ধির নিয়ম (অ + আ = আ)। ‘রত্ন’ (মণি-মুক্তা) এবং ‘আকর’ (খনি/উৎস) মিলে গঠিত হয়েছে ‘রত্নাকর’, যার অর্থ সমুদ্র বা রত্নের আধার।',
            'ক্রিয়াপদের মূল অংশকে বলা হয়-' => '<strong>ধাতু</strong>: ক্রিয়াপদকে বিশ্লেষণ করলে দুটি অংশ পাওয়া যায়—ধাতু (ক্রিয়ামূল) এবং ক্রিয়া-বিভক্তি। যেমন: ‘পড়ছে’ = পড়্ (ধাতু) + ছে (বিভক্তি)।',
            'বাংলায় টি. এস. এলিয়টের কবিতার প্রথম অনুবাদক-' => '<strong>রবীন্দ্রনাথ ঠাকুর</strong>: আধুনিক ইংরেজি সাহিত্যের অন্যতম শ্রেষ্ঠ কবি টি. এস. এলিয়টের (T. S. Eliot) কবিতা বাংলায় প্রথম অনুবাদ করেন রবীন্দ্রনাথ ঠাকুর। তিনি এলিয়টের ‘Journey of the Magi’ কবিতাটি ‘তীর্থযাত্রী’ নামে অনুবাদ করেছিলেন।',
            '‘অগ্নিবীণা’ কাব্যগ্রন্থের সংকলিত প্রথম কবিতা-' => '<strong>প্রলয়োল্লাস</strong>: জাতীয় কবি কাজী নজরুল ইসলামের প্রথম প্রকাশিত বিখ্যাত কাব্যগ্রন্থ ‘অগ্নিবীণা’ (১৯২২)। এতে সংকলিত প্রথম কবিতা ‘প্রলয়োল্লাস’ (তোরা সব জয়ধ্বনি কর!) এবং দ্বিতীয় কবিতা ‘বিদ্রোহী’। এতে মোট ১২টি কবিতা রয়েছে।',
            '‘শেষের কবিতা’ রবীন্দ্রনাথ রচিত-' => '<strong>উপন্যাস</strong>: ‘শেষের কবিতা’ রবীন্দ্রনাথ ঠাকুরের একটি বিখ্যাত রোমান্টিক ভাবপ্রধান আধুনিক উপন্যাস (১৯২৯)। এর প্রধান চরিত্র অমিত রায় ও লাবণ্য।',
            '‘আমার ভাইয়ের রক্তে রাঙানো ২১ শে ফেব্রুয়ারি’র রচয়িতা কে?' => '<strong>আবদুল গাফফার চৌধুরী</strong>: ভাষা আন্দোলনের অমর এ গানটির রচয়িতা সাংবাদিক ও কলামিস্ট আবদুল গাফফার চৌধুরী। গানটির বর্তমান সুরকার আলতাফ মাহমুদ (প্রথম সুরকার ছিলেন আবদুল লতিফ)।',
            'কোন দ্বিরুক্তি শব্দজুটি বহুবচন সংকেত করে?' => '<strong>পাকা পাকা আম</strong>: বিশেষ্য বা বিশেষণ শব্দের দ্বিরুক্ত প্রয়োগের মাধ্যমে বহুবচন বোঝায়। ‘পাকা পাকা আম’ দ্বারা অনেকগুলো পাকা আমকে নির্দেশ করা হয়েছে।',
            'কোন প্রবচন বাক্য ব্যবহারিক দিক হতে সঠিক?' => '<strong>অধিক সন্ন্যাসীতে গাজন নষ্ট</strong>: এটি একটি বহুল প্রচলিত প্রবাদ প্রবচন, যার অর্থ—কোনো কাজে অতিরিক্ত দায়িত্বপ্রাপ্ত ব্যক্তি নিয়োজিত হলে সমন্বয়ের অভাবে কাজটি পণ্ড বা বিনষ্ট হয়।',
            'কোন বাক্যে ‘মাথা’ শব্দটি বুদ্ধি অর্থে ব্যবহৃত?' => '<strong>মাথা খাটিয়ে কাজ করবে</strong>: এখানে ‘মাথা’ শব্দের অর্থ মেধা, প্রজ্ঞা বা বুদ্ধি খাটানো। বাকি বাক্যগুলোতে ‘মাথা’ শারীরিক অঙ্গ বা অন্য অর্থে ব্যবহৃত হয়েছে।',
            'কোন শব্দে বিদেশি উপসর্গ ব্যবহৃত হয়েছে?' => '<strong>নিমরাজি</strong>: ‘নিম’ একটি ফারসি উপসর্গ, যার অর্থ অর্ধেক বা আংশিক। ‘নিমরাজি’ শব্দের অর্থ অর্ধ-সম্মত বা অনিচ্ছাসত্ত্বেও রাজি হওয়া।',
            'কোনটি তদ্ভব শব্দ?' => '<strong>চাঁদ</strong>: সংস্কৃত ‘চন্দ্র’ প্রাকৃত হয়ে ‘চন্দ’ এবং পরবর্তীতে বাংলায় পরিবর্তিত হয়ে ‘চাঁদ’ হয়েছে। যে শব্দগুলো সংস্কৃত থেকে প্রাকৃতের মধ্য দিয়ে পরিবর্তিত হয়ে বাংলায় এসেছে সেগুলোকে তদ্ভব বা খাঁটি বাংলা শব্দ বলে।',
            '‘উভয়কূল রক্ষা’ অর্থে ব্যবহৃত প্রবচন কোনটি?' => '<strong>সাপও মরে, লাঠিও না ভাঙ্গে</strong>: এমন কৌশল অবলম্বন করা যাতে প্রতিকূল পরিস্থিতি দূর হয় কিন্তু কোনো পক্ষেরই ক্ষতি না হয়, অর্থাৎ উভয়কূল বজায় থাকে।',
            'Choose the correct alternative to complete the sentence: "He ____ to see us if he had been able to"' => '<strong>would have come</strong>: এটি Third Conditional-এর নিয়ম। \'If + past perfect tense\' থাকলে অপর ক্লজে \'subject + would have / could have / might have + V3\' বসে।',
            'Choose the appropriate alternative to complete the sentence: "He had a .... of fever."' => '<strong>severe attack</strong>: জ্বরের তীব্র আক্রমণ বোঝাতে কলোকেশন (collocation) হিসেবে \'severe attack of fever\' ব্যবহৃত হয়।',
            'Choose the correct sentence:' => 'বাক্যের পদসংস্থান ও ব্যাকরণিক নিয়ম অনুযায়ী সাবজেক্ট-ভার্ব এগ্রিমেন্ট ও প্রেপজিশন যথাযথ রয়েছে।',
            'Choose the correct sentence:' => 'বাক্যের পদসংস্থান ও ব্যাকরণিক নিয়ম অনুযায়ী সাবজেক্ট-ভার্ব এগ্রিমেন্ট ও প্রেপজিশন যথাযথ রয়েছে।',
            'Choose the correct sentence:' => 'বাক্যের পদসংস্থান ও ব্যাকরণিক নিয়ম অনুযায়ী সাবজেক্ট-ভার্ব এগ্রিমেন্ট ও প্রেপজিশন যথাযথ রয়েছে।',
            'Choose the correct answer: "How long did you wait?"' => '<strong>Till he came</strong>: \'How long\' দ্বারা সময়ের স্থায়িত্ব জানতে চাওয়া হয়েছে। উত্তর হিসেবে \'Till he came\' (তিনি আসা পর্যন্ত) সময় নির্দেশক সঠিক ক্লজ।',
            'What will be the correct preposition to complete the sentence? "I am not bad ... tennis."' => '<strong>at</strong>: কোনো নির্দিষ্ট বিষয় বা খেলাধুলায় দক্ষতা/অদক্ষতা প্রকাশ করতে \'good at\' বা \'bad at\' এপ্রোপ্রিয়েট প্রিপজিশন বসে।',
            'What is the antonym of ‘gentle’?' => '<strong>Harsh</strong>: \'Gentle\' অর্থ শান্ত, নম্র বা ভদ্র। এর বিপরীতার্থক শব্দ হলো \'Harsh\' (কঠোর, রূঢ় বা কর্কশ)।',
            'What is the synonym of ‘Jovial’?' => '<strong>Jolly</strong>: \'Jovial\' অর্থ প্রফুল্ল, আমুদে বা হাস্যোজ্জ্বল। এর সমার্থক শব্দ হলো \'Jolly\' বা \'Cheerful\'।',
            'What is the synonym of ‘Competent’?' => '<strong>Capable</strong>: \'Competent\' অর্থ যোগ্য, দক্ষ বা উপযুক্ত। এর সঠিক সমার্থক শব্দ হলো \'Capable\' বা \'Skilled\'।',
            'Who is the author of ‘A Farewell to Arms’?' => '<strong>Ernest Hemingway</strong>: নোবেলবিজয়ী মার্কিন সাহিত্যিক আর্নেস্ট হেমিংওয়ের প্রথম বিশ্বযুদ্ধের পটভূমিতে রচিত বিখ্যাত যুদ্ধবিরোধী উপন্যাস হলো \'A Farewell to Arms\' (১৯২৯)।',
            'Who is the author of ‘Animal Farm’?' => '<strong>George Orwell</strong>: ব্রিটিশ লেখক জর্জ অরওয়েল ১৯৪৫ সালে রাজনৈতিক ব্যঙ্গধর্মী উপন্যাস \'Animal Farm\' রচনা করেন, যেখানে সোভিয়েত সমাজতন্ত্রের স্বৈরতান্ত্রিক রূপকে রূপকভাবে তুলে ধরা হয়েছে।',
            'Who is the author of ‘India Wins Freedom’?' => '<strong>Abul Kalam Azad</strong>: ভারতের স্বাধীনতা আন্দোলনের শীর্ষ নেতা ও ভারতের প্রথম শিক্ষামন্ত্রী মাওলানা আবুল কালাম আজাদ রচিত বিখ্যাত আত্মজীবনীমূলক গ্রন্থ হলো \'India Wins Freedom\'।',
            'What kind of noun is ‘Cattle’?' => '<strong>Collective</strong>: \'Cattle\' (গবাদিপশুর পাল) দ্বারা একাধিক প্রাণীর সমষ্টিকে বোঝায়। এটি একটি Collective Noun যা সবসময় বহুবচন হিসেবে ব্যবহৃত হয়।',
            'What kind of noun is ‘Girl’?' => '<strong>Common</strong>: \'Girl\' দ্বারা কোনো নির্দিষ্ট মেয়েকে না বুঝিয়ে একজাতীয় সকল মেয়েকে সাধারণভাবে বোঝায়, তাই এটি Common Noun (জাতিবাচক বিশেষ্য)।',
            'What is the meaning of ‘White Elephant’?' => '<strong>A very costly or troublesome possession</strong>: ইডিয়ম \'White Elephant\' দ্বারা এমন মূল্যবান জিনিস বোঝায় যা বজায় রাখতে প্রচুর খরচ হয় কিন্তু বাস্তবে কোনো উপকারে আসে না।',
            'বাংলাদেশ গণপ্রজাতন্ত্রের ঘোষণা হয়েছিল-' => '<strong>১০ এপ্রিল, ১৯৭১</strong>: ১৯৭১ সালের ১০ এপ্রিল মুজিবনগরে স্বাধীন সার্বভৌম বাংলাদেশ গণপ্রজাতন্ত্র ও স্বাধীনতার ঘোষণাপত্র (Proclamation of Independence) আনুষ্ঠানিকভাবে অনুমোদিত ও গৃহীত হয় এবং ১৭ এপ্রিল তা আনুষ্ঠানিকভাবে পাঠ করা হয়।',
            'গণপ্রজাতন্ত্রী বাংলাদেশের সংবিধান প্রবর্তিত হয়-' => '<strong>১৬ ডিসেম্বর, ১৯৭২</strong>: বাংলাদেশের সংবিধান ১৯৭২ সালের ৪ নভেম্বর গণপরিষদে গৃহীত হয় এবং বিজয় দিবস উপলক্ষে ১৬ ডিসেম্বর ১৯৭২ থেকে আনুষ্ঠানিকভাবে কার্যকর বা প্রবর্তিত হয়।',
            'বিখ্যাত সাধক শাহ সুলতান বলখীর মাজার কোথায়?' => '<strong>মহাস্থানগড়ে</strong>: একাদশ শতকের বিখ্যাত সুফি সাধক হজরত শাহ সুলতান বলখী (র.) এর মাজার বগুড়া জেলার প্রাচীন ঐতিহাসিক স্থান মহাস্থানগড়ে অবস্থিত।',
            'বাংলাদেশের লোকশিল্প জাদুঘর কোথায়?' => '<strong>সোনারগাঁওয়ে</strong>: শিল্পাচার্য জয়নুল আবেদিনের উদ্যোগে ১৯৭৫ সালে নারায়ণগঞ্জের প্রাচীন রাজধানী সোনারগাঁওয়ে বাংলাদেশ লোক ও কারুশিল্প জাদুঘর প্রতিষ্ঠিত হয়।',
            'বাংলায় ইউরোপীয় বণিকদের মধ্যে বাণিজ্যের উদ্দেশ্যে প্রথম এসেছিলেন-' => '<strong>পর্তুগিজরা</strong>: ১৪৯৮ সালে ভাস্কো দা গামা ভারতে আসেন এবং ১৫১৬-১৭ সালের দিকে ইউরোপীয় বণিকদের মধ্যে সর্বপ্রথম পর্তুগিজরা বাংলায় বাণিজ্য করার উদ্দেশ্যে আগমন করে।',
            'বাংলা নববর্ষ পহেলা বৈশাখ চালু করেছিলেন কে?' => '<strong>সম्राट আকবর</strong>: মুঘল সম্রাট আকবর খাজনা আদায়ের সুবিধার্থে ১৫৮৪ খ্রিষ্টাব্দে সৌরবর্ষের ওপর ভিত্তি করে ফসলি সন প্রবর্তন করেন, যা পরবর্তীতে বাংলা সন বা বঙ্গাব্দ হিসেবে রূপ নেয়।',
            'পাহাড়পুরের বৌদ্ধ বিহারটি কি নামে পরিচিত ছিল?' => '<strong>সোমপুর বিহার</strong>: নওগাঁ জেলার বদলগাছী উপজেলায় অবস্থিত অষ্টম শতাব্দীর পাল রাজা ধর্মপাল কর্তৃক নির্মিত পাহাড়পুরের ঐতিহাসিক বৌদ্ধ বিহারটি ‘সোমপুর বিহার’ বা সোমপুর মহাবিহার নামে পরিচিত। এটি ইউনেস্কো বিশ্ব ঐতিহ্যবাহী স্থান।',
            'বাংলাদেশে চীনামাটির সন্ধান পাওয়া গেছে-' => '<strong>বিজয়পুরে</strong>: নেত্রকোণা জেলার দুর্গাপুর উপজেলার বিজয়পুরে বাংলাদেশের সবচেয়ে বড় ও উন্নত মানের চীনামাটি (শ্বেত মৃত্তিকা) খনি অবস্থিত।',
            'ঢাকা বিশ্ববিদ্যালয় প্রতিষ্ঠিত হয় কোন সালে?' => '<strong>১৯২১</strong>: নাথান কমিটির সুপারিশের ভিত্তিতে ১৯২১ সালের ১ জুলাই ঢাকা বিশ্ববিদ্যালয় তার শিক্ষা কার্যক্রম শুরু করে। এর প্রথম উপাচার্য ছিলেন স্যার পি. জে. হার্টগ।',
            'ঢাকার বিখ্যাত তারা মসজিদ তৈরি করেন?' => '<strong>মির্জা আহমেদ জান</strong>: ঢাকার আরমানিটোলায় অবস্থিত তারা মসজিদ (সিতারা মসজিদ) উনিশ শতকের শুরুর দিকে মির্জা আহমেদ জান (মির্জা গোলাম পীর) তৈরি করেছিলেন। পরবর্তীতে ১৯২৬ সালে আলী জান ব্যাপারী এতে তারকাখচিত নকশা সংযোজন করেন।',
            'পাখি ছাড়া ‘বলাকা’ ও ‘দোয়েল’ কিসের নাম?' => '<strong>উন্নত জাতের গম শস্য</strong>: বাংলাদেশে কৃষি গবেষণায় উদ্ভাবিত দুটি উচ্চফলনশীল গমের জাত হলো ‘বলাকা’ ও ‘দোয়েল’।',
            '‘অগ্নিশ্বর’, ‘কানাইবাঁশী’, ‘মোহনবাঁশী’ ও ‘বীটজবা’ কি জাতীয় ফলের নাম?' => '<strong>কলা</strong>: এগুলো বাংলাদেশে প্রচলিত উচ্চফলনশীল ও দেশীয় সুস্বাদু কলার উন্নত জাত।',
            'বাংলায় চিরস্থায়ী বন্দোবস্ত প্রবর্তন করা হয় কোন সালে?' => '<strong>১৭৯৩ সালে</strong>: ব্রিটিশ গভর্নর জেনারেল লর্ড কর্নওয়ালিস ১৭৯৩ সালের ২২ মার্চ বাংলায় জমিদারি ও ভূমি রাজস্ব আদায়ের লক্ষ্যে চিরস্থায়ী বন্দোবস্ত (Permanent Settlement) চালু করেন।',
            'কোন মুঘল সম্রাট বাংলার নাম দেন ‘জান্নাতাবাদ’?' => '<strong>হুমায়ুন</strong>: ১৫৩৮ খ্রিষ্টাব্দে মুঘল সম্রাট হুমায়ুন গৌড় বা বাংলার অপরূপ সৌন্দর্য ও প্রাকৃতিক সম্পদে মুগ্ধ হয়ে গৌড়ের নাম দেন ‘জান্নাতাবাদ’ (স্বর্গীয় শহর)।',
            'উপমহাদেশের মধ্যে ঢাকা বিশ্ববিদ্যালয়ের প্রথম ভাইস চ্যান্সেলর-' => '<strong>স্যার এ. এফ. রহমান</strong>: ঢাকা বিশ্ববিদ্যালয়ের প্রথম ভারতীয় ও উপমহাদেশের বংশোদ্ভূত উপাচার্য ছিলেন স্যার আহমেদ ফজলুর রহমান (স্যার এ. এফ. রহমান), যিনি ১৯৩৪ থেকে ১৯৩৮ সাল পর্যন্ত দায়িত্ব পালন করেন। (প্রথম উপাচার্য ছিলেন পি. জে. হার্টগ)।',
            '১৯৮৮ সালের সিউল অলিম্পিকে বাংলাদেশের কোন ভাস্করের শিল্পকর্ম প্রদর্শনীতে স্থান পায়?' => '<strong>হামিদুজ্জামান খান</strong>: ১৯৮৮ সালের দক্ষিণ কোরিয়ার সিউল অলিম্পিক ভাস্কর্য পার্কে বাংলাদেশের বিশিষ্ট ভাস্কর হামিদুজ্জামান খানের ‘Peace Bird’ বা শান্তির পাখি ভাস্কর্যটি স্থায়ীভাবে প্রদর্শিত ও স্থাপিত হয়।',
            'ঢাকা কখন সর্বপ্রথম বাংলার রাজধানী হয়েছিল?' => '<strong>১৬১০ সালে</strong>: মুঘল সুবেদার ইসলাম খাঁ চিশতি ১৬১০ খ্রিষ্টাব্দে ঢাকাকে সর্বপ্রথম সুবে বাংলার রাজধানী করেন এবং সম্রাট জাহাঙ্গীরের নামানুসারে এর নাম রাখেন ‘জাহাঙ্গীরনগর’।',
            'পূর্বাশা দ্বীপের অপর নাম -' => '<strong>দক্ষিণ তালপট্টি</strong>: সাতক্ষীরা জেলার হাড়িয়াভাঙা নদীর মোহনায় জেগে ওঠা এই বিতর্কিত দ্বীপটিকে বাংলাদেশ বলতো ‘দক্ষিণ তালপট্টি দ্বীপ’ এবং ভারত বলতো ‘পূর্বাশা’ বা ‘নিউ মুর দ্বীপ’। পরবর্তীতে সমুদ্রের ভাঙনে এটি তলিয়ে যায়।',
            '‘সার্ক’ এর প্রথম শীর্ষ বৈঠক অনুষ্ঠিত হয়-' => '<strong>১৯৮৫ সালে</strong>: দক্ষিণ এশীয় আঞ্চলিক সহযোগিতা সংস্থা (SAARC) এর প্রথম শীর্ষ সম্মেলন ১৯৮৫ সালের ৭-৮ ডিসেম্বর বাংলাদেশের রাজধানী ঢাকায় অনুষ্ঠিত হয়।',
            'আরব রাষ্ট্রগুলোর মধ্যে কোনটি বাংলাদেশকে প্রথম স্বীকৃতি দেয়?' => '<strong>ইরাক</strong>: মধ্যপ্রাচ্য ও আরব দেশগুলোর মধ্যে ইরাক সর্বপ্রথম ১৯৭২ সালের ৮ জুলাই স্বাধীন বাংলাদেশকে কূটনৈতিক স্বীকৃতি প্রদান করে।',
            '‘পিএলও’ এর সদর দপ্তর-' => '<strong>রামাল্লা</strong>: প্যালেস্টাইন লিবারেশন অর্গানাইজেশন (PLO) ১৯৬৪ সালে গঠিত হয়। পূর্বে তিউনিসিয়ার তিউনিসে সদর দপ্তর থাকলেও অসলো চুক্তির পর বর্তমানে এর প্রশাসনিক সদর দপ্তর ফিলিস্তিনের পশ্চিম তীরের রামাল্লায় অবস্থিত।',
            'জাতিসংঘের প্রথম মহাসচিব ছিলেন-' => '<strong>ট্রিগভেলি</strong>: নরওয়ের নাগরিক ট্রিগভেলি (Trygve Lie) ১৯৪৬ থেকে ১৯৫২ সাল পর্যন্ত জাতিসংঘের প্রথম নির্বাচিত মহাসচিব হিসেবে দায়িত্ব পালন করেন।',
            'নিরাপত্তা পরিষদের এশীয় আসনে বাংলাদেশের প্রতিদ্বন্দ্বী ছিল-' => '<strong>জাপান</strong>: ১৯৭৮ সালে জাতিসংঘ নিরাপত্তা পরিষদের অস্থায়ী এশীয় সদস্যপদের নির্বাচনে বাংলাদেশ জাপানের মতো পরাশক্তিকে পরাজিত করে ঐতিহাসিক বিজয় অর্জন করেছিল।',
            'সাধারণ পরিষদের নিয়মিত অধিবেশন শুরু হয়-' => '<strong>সেপ্টেম্বর মাসের তৃতীয় মঙ্গলবার</strong>: জাতিসংঘের সাধারণ পরিষদের (UNGA) বার্ষিক নিয়মিত অধিবেশন প্রতি বছর সেপ্টেম্বর মাসের তৃতীয় মঙ্গলবার শুরু হয়।',
            'জাতিসংঘের বর্তমান সদস্য সংখ্যা কত?' => '<strong>১৯৩</strong>: ২০১১ সালে দক্ষিণ সুদান জাতিসংঘের ১৯৩তম সদস্য হিসেবে অন্তর্ভুক্ত হয়। সর্বশেষ সদস্য দেশ দক্ষিণ সুদান।',
            'ইসলামিক সম্মেলন সংস্থার সচিবালয় কোথায়?' => '<strong>জেদ্দা</strong>: ১৯৬৯ সালে গঠিত অর্গানাইজেশন অব ইসলামিক কোঅপারেশন (OIC) এর স্থায়ী সচিবালয় ও সদর দপ্তর সৌদি আরবের জেদ্দা শহরে অবস্থিত।',
            'যে দেশ ‘এসডিআই’ প্রতিরক্ষা কর্মসূচি গ্রহণ করেছে-' => '<strong>যুক্তরাষ্ট্র</strong>: ১৯৮৩ সালে মার্কিন প্রেসিডেন্ট রোনাল্ড রিগান মহাকাশভিত্তিক ব্যালিস্টিক ক্ষেপণাস্ত্র প্রতিরক্ষাব্যবস্থা \'Strategic Defense Initiative\' (SDI) বা \'Star Wars\' কর্মসূচি ঘোষণা করেন।',
            'ব্রিটেনের প্রশাসনিক সদর দপ্তরকে বলা হয়-' => '<strong>হোয়াইট হল</strong>: লন্ডনের প্রশাসনিক ও সরকারি মন্ত্রণালয়গুলোর মিলনকেন্দ্র সড়কটিকে ‘হোয়াইট হল’ (Whitehall) বলা হয়, যা ব্রিটিশ সরকারের প্রশাসনিক প্রতীক।',
            'দ্বিতীয় মহাযুদ্ধে জার্মানি আত্মসমর্পণ করে-' => '<strong>১৯৪৫ সালের মে মাসে</strong>: দ্বিতীয় বিশ্বযুদ্ধের ইউরোপীয় ফ্রন্টে সোভিয়েত ও মিত্রবাহিনীর কাছে নাৎসি জার্মানি ১৯৪৫ সালের ৮ মে নিঃশর্ত আত্মসমর্পণ করে (Victory in Europe Day)।',
            'কঙ্গোকে বিদেশি শাসন থেকে মুক্ত করার লড়াইয়ে চিরস্থায়ী নাম-' => '<strong>প্যাট্রিক লুমুম্বা</strong>: বেলজিয়ামের ঔপনিবেশিক শাসন থেকে কঙ্গোর স্বাধীনতা আন্দোলনের অবিসংবাদিত নেতা ও স্বাধীন কঙ্গোর প্রথম গণতান্ত্রিক প্রধানমন্ত্রী ছিলেন প্যাট্রিক লুমুম্বা।',
            'হিরোশিমায় এটম বোমা ফেলা হয়েছিল-' => '<strong>১৯৪৫ সালের আগস্ট মাসে</strong>: দ্বিতীয় বিশ্বযুদ্ধের শেষলগ্নে ১৯৪৫ সালের ৬ আগস্ট মার্কিন যুক্তরাষ্ট্র জাপানের হিরোশিমা শহরে ‘লিটল বয়’ নামক প্রথম পারমাণবিক বোমা নিক্ষেপ করে এবং ৯ আগস্ট নাগাসাকিতে ‘ফ্যাট ম্যান’ নিক্ষেপ করে।',
            '‘আইএমএফ’ এর সদর দপ্তর কোথায়?' => '<strong>ওয়াশিংটন</strong>: ১৯৪৪ সালের ব্রেটন উডস সম্মেলনের মাধ্যমে প্রতিষ্ঠিত আন্তর্জাতিক মুদ্রা তহবিল (IMF) এবং বিশ্বব্যাংক (World Bank) উভয়ের সদর দপ্তর যুক্তরাষ্ট্রের ওয়াশিংটন ডি.সি.-তে অবস্থিত।',
            'নিকারাগুয়ার যে বিদ্রোহীরা যুক্তরাষ্ট্র সমর্থনপুষ্ট তার নাম-' => '<strong>কন্ট্রা</strong>: ১৯৮০-এর দশকে নিকারাগুয়ার বামপন্থী স্যান্ডিনিস্তা সরকারের বিরুদ্ধে মার্কিন যুক্তরাষ্ট্রের অর্থ ও অস্ত্রে মদদপুষ্ট ডানপন্থী বিদ্রোহীদের ‘কন্ট্রা’ (Contras) বলা হতো।',
            '‘ব্যাবিলনের ঝুলন্ত উদ্যান’ কোন দেশে অবস্থিত?' => '<strong>ইরাক</strong>: প্রাচীন পৃথিবীর সপ্তাশ্চর্যের অন্যতম ‘ব্যাবিলনের ঝুলন্ত উদ্যান’ বর্তমান ইরাকের ইউফ্রেটিস নদীর তীরে খ্রিস্টপূর্ব ষষ্ঠ শতকে রাজা নেবুচাদনেজার দ্বিতীয় তাঁর স্ত্রীর জন্য নির্মাণ করেছিলেন।',
            'ইতিহাস বিখ্যাত ট্রয় নগরী কোথায়?' => '<strong>তুরস্কে</strong>: গ্রিক মহাকবি হোমারের ‘ইলিয়াড’ মহাকাব্যে বর্ণিত ট্রোজান যুদ্ধের ঐতিহাসিক ট্রয় নগরী বর্তমান তুরস্কের আনাতোলিয়া বা উত্তর-পশ্চিমাঞ্চলীয় উপকূলে অবস্থিত।',
            'নবায়নযোগ্য শক্তি উৎসের একটি উদাহরণ হলো-' => '<strong>সূর্য</strong>: সৌরশক্তি, বায়ুপ্রবাহ ও জলবিদ্যুৎ ইত্যাদি উৎস ব্যবহারের সাথে সাথে শেষ হয়ে যায় না এবং বারবার ব্যবহার করা যায়, তাই সূর্য একটি অফুরন্ত নবায়নযোগ্য শক্তি উৎস।',
            'প্রেসার কুকারে রান্না তাড়াতাড়ি হয়, কারণ-' => '<strong>উচ্চ চাপে তরলের স্ফুটনাংক বৃদ্ধি পায়</strong>: আবদ্ধ পাত্রে বাষ্পের চাপ বৃদ্ধি পেলে পানির স্ফুটনাংক ১০০° সেলসিয়াসের চেয়ে বেড়ে প্রায় ১২০° সেলসিয়াস পর্যন্ত পৌঁছায়, যার ফলে খাবার দ্রুত সেদ্ধ হয়।',
            'যে তিনটি মূখ্য বর্ণের সমন্বয়ে অন্যান্য বর্ণ সৃষ্টি করা যায়, সেগুলো হলো-' => '<strong>লাল, নীল, সবুজ</strong>: আলোকবিজ্ঞানে লাল (Red), সবুজ (Green) ও নীল (Blue)—এই তিনটি হলো মৌলিক বা প্রাইমারি বর্ণ (RGB)। এদের বিভিন্ন অনুপাতে মিশ্রণে অন্যান্য সকল বর্ণ পাওয়া যায়।',
            'ভৌগোলিকভাবে গুরুত্বপূর্ণ একটি কাল্পনিক রেখা বাংলাদেশের উপর দিয়ে গিয়েছে, সেটি হচ্ছে-' => '<strong>কর্কটক্রান্তি রেখা</strong>: ২৩.৫° উত্তর অক্ষাংশ রেখাটি হলো কর্কটক্রান্তি রেখা (Tropic of Cancer), যা বাংলাদেশের প্রায় মধ্যভাগ দিয়ে (কুষ্টিয়া, চুয়াডাঙ্গা, পাবনা, ঢাকা, কুমিল্লা ও খাগড়াছড়ি) অতিক্রম করেছে।',
            'মাছ অক্সিজেন নেয়-' => '<strong>পানির মধ্যে দ্রবীভূত বাতাস হতে</strong>: মাছ ফুলকার (gills) সাহায্যে পানির সংস্পর্শে এসে পানিতে দ্রবীভূত অক্সিজেন শোষণ করে এবং রক্তসঞ্চালনে পাঠায়।',
            'কচুশাক বিশেষভাবে মূল্যবান যে উপাদানের জন্য তা হলো-' => '<strong>লৌহ</strong>: কচুশাকে প্রচুর পরিমাণে উদ্ভিজ্জ আয়রন বা লৌহ (Iron) এবং ভিটামিন ‘এ’ থাকে, যা মানবদেহের রক্তস্বল্পতা (এনিমিয়া) দূর করতে ও দৃষ্টিশক্তি ভালো রাখতে সাহায্য করে।',
            'সাধারণ ড্রাইসেলে ইলেকট্রোড হিসেবে থাকে-' => '<strong>কার্বন দণ্ড ও দস্তার কৌটা</strong>: ড্রাইসেলে অ্যানোড হিসেবে থাকে দস্তার (Zinc) তৈরি বহিরাবরণ এবং ক্যাথোড হিসেবে কেন্দ্রে একটি কার্বন দণ্ড (গ্রাফাইট) থাকে।',
            'দূরের বিদ্যুৎ উৎপাদন কেন্দ্র হতে বিদ্যুৎ নিয়ে আসতে হলে হাইভোল্টেজ ব্যবহার করার কারণ-' => '<strong>এতে বিদ্যুৎ এর অপচয় কম হয়</strong>: উচ্চ ভোল্টেজে বিদ্যুৎ সঞ্চালন করলে লাইনের তড়িৎ প্রবাহ (I) হ্রাস পায়। ফলে তারে উৎপন্ন তাপজনিত শক্তির অপচয় (P = I²R) বহুলাংশে কমে যায়।',
            'সংকর ধাতু পিতলের উপাদান হলো-' => '<strong>তামা ও দস্তা</strong>: পিতল (Brass) হলো তামা (Copper ~ ৭০%) এবং দস্তা (Zinc ~ ৩০%) এর একটি বিখ্যাত মিশ্রণ বা সংকর ধাতু। (অপরদিকে ব্রোঞ্জ হলো তামা ও টিনের মিশ্রণ)।',
            'আমাদের দেহকোষ রক্ত হতে গ্রহণ করে-' => '<strong>অক্সিজেন ও গ্লুকোজ</strong>: রক্ত ফুসফুস থেকে অক্সিজেন এবং পরিপাকনালী থেকে শোষিত গ্লুকোজ দেহের প্রতিটি সজীব কোষে পৌঁছে দেয়, যা কোষীয় শ্বসনে শক্তি উৎপাদনে ব্যবহৃত হয়।',
            'পৃথিবীর ঘূর্ণনের ফলে আমরা ছিটকে পড়ি না-' => '<strong>মাধ্যাকর্ষণ বলের জন্য</strong>: পৃথিবী তার কেন্দ্রাভিমুখী শক্তিশালী মাধ্যাকর্ষণ বল (Gravitational Force) দ্বারা ভূপৃষ্ঠের প্রতিটি বস্তুকে আকর্ষণ করে ধরে রাখে, যার মান ঘূর্ণনজনিত কেন্দ্রাতিগ বলের চেয়ে অনেক বেশি।',
            'নিচের কোনটি জীবাশ্ম জ্বালানি নয়?' => '<strong>বায়োগ্যাস</strong>: কয়লা, পেট্রোলিয়াম এবং প্রাকৃতিক গ্যাস প্রাগৈতিহাসিক জৈব অবশেষ থেকে মাটির গভীরে তৈরি জীবাশ্ম জ্বালানি। কিন্তু বায়োগ্যাস হলো পশু-পাখির মলমূত্র পচিয়ে তৈরি সাম্প্রতিক নবায়নযোগ্য জৈব জ্বালানি।',
            'বৈদ্যুতিক মোটর এমন একটি যন্ত্রকৌশল যা-' => '<strong>তড়িৎ শক্তিকে যান্ত্রিক শক্তিতে রূপান্তরিত করে</strong>: তড়িৎচুম্বকীয় আবেশ ও লরেঞ্জ বলের নীতি কাজে লাগিয়ে বৈদ্যুতিক মোটর বিদ্যুৎ শক্তি গ্রহণ করে ঘূর্ণনশীল যান্ত্রিক শক্তিতে রূপান্তর করে (যেমন: ফ্যান, পাম্প)।',
            'যে বায়ু সর্বদাই উচ্চচাপ অঞ্চল থেকে নিম্নচাপ অঞ্চলের দিকে প্রবাহিত হয় তাকে বলা হয়-' => '<strong>নিয়ত বায়ু</strong>: বছরের প্রতিটি ঋতুতে পৃথিবীর স্থায়ী উচ্চচাপ বলয় থেকে নিম্নচাপ বলয়ের দিকে নির্দিষ্ট দিকে নিয়মিত প্রবাহিত বাতাসকে নিয়ত বায়ু (Planetary Wind - যেমন আয়ন বায়ু, পশ্চিমা বায়ু) বলে।',
            'জলজ উদ্ভিদ সহজে ভাসতে পারে, কারণ-' => '<strong>এদের কান্ডে অনেক বায়ু কুঠুরী থাকে</strong>: কচুরিপানা বা পদ্মের মতো জলজ উদ্ভিদের অ্যারেনকাইমা কোষে বড় বড় বায়ু কুঠুরী (Air chambers) থাকে, যা উদ্ভিদটিকে হালকা করে পানির উপর ভাসমান থাকতে সাহায্য করে।',
            '১ থেকে ৩০ পর্যন্ত কয়টি মৌলিক সংখ্যা আছে?' => '<strong>১০টি</strong>: ১ থেকে ৩০ এর মধ্যকার মৌলিক সংখ্যাগুলো হলো: ২, ৩, ৫, ৭, ১১, ১৩, ১৭, ১৯, ২৩, এবং ২৯। সর্বমোট ১০টি মৌলিক সংখ্যা রয়েছে।',
            'নিচের কোন সংখ্যাটি মৌলিক সংখ্যা?' => '<strong>৪৭</strong>: যে সংখ্যাকে ১ এবং সেই সংখ্যা ছাড়া অন্য কোনো সংখ্যা দ্বারা নিঃশেষে ভাগ করা যায় না তা মৌলিক সংখ্যা। ৪৭ একটি অবিভাজ্য মৌলিক সংখ্যা (বাকি অপশন যেমন ৩৫ = ৫×৭, ৮৭ = ৩×২৯, ৯১ = ৭×১৩ যৌগিক সংখ্যা)।',
            'দুটি সংখ্যার গুণফল ১৫৩৬। সংখ্যা দুটির ল.সা.গু ৯৬ হলে, গ.সা.গু কত?' => '<strong>১৬</strong>: আমরা জানি, দুটি সংখ্যার গুণফল = ল.সা.গু × গ.সা.গু। অতএব, গ.সা.গু = গুণফল ÷ ল.সা.গু = ১৫৩৬ ÷ ৯৬ = ১৬।',
            '(.১ × .০১ × .০০১) / (.২ × .০২ × .০০২) এর মান কত?' => '<strong>1/8</strong>: (.১ × .০১ × .০০১) / (.২ × .০২ × .০০২) = (.১/.২) × (.০১/.০২) × (.০০১/.০০২) = (১/২) × (১/২) × (১/২) = ১/৮।',
            'চিনির মূল্য ২৫% বৃদ্ধি পাওয়াতে একটি পরিবার চিনি খাওয়া এমনভাবে কমাল যে, চিনি বাবদ ব্যয় বৃদ্ধি পেল না। ঐ পরিবার চিনি খাওয়ার খরচ শতকরা কত কমিয়েছিল?' => '<strong>২০%</strong>: শতকরা হ্রাসের সূত্র = [১০০ × বৃদ্ধির হার] / [১০০ + বৃদ্ধির হার] = (১০০ × ২৫) / (১০০ + ২৫) = ২৫০০ / ১২৫ = ২০%।',
            'টাকায় ৩টি করে আম কিনে টাকায় ২টি আম বিক্রয় করলে শতকরা কত লাভ হবে?' => '<strong>৫০%</strong>: ১টি আমের ক্রয়মূল্য = ১/৩ টাকা, ১টি আমের বিক্রয়মূল্য = ১/২ টাকা। লাভ = ১/২ - ১/৩ = ১/৬ টাকা। শতকরা লাভ = [(১/৬) ÷ (১/৩)] × ১০০ = (৩/৬) × ১০০ = ৫০%।',
            'সরল সুদের হার শতকরা কত টাকা হলে যে কোন মূলধন ৮ বছরের সুদে-আসলে তিনগুণ হবে?' => '<strong>২৫ টাকা</strong>: মূলধন P হলে সুদে-আসলে ৩P। অতএব সুদ I = ৩P - P = ২P। সূত্র: I = Pnr ⇒ ২P = P × ৮ × r ⇒ r = ২/৮ = ১/৪ = ২৫%।',
            '৬০ লিটার কেরোসিন ও পেট্রোলের মিশ্রণের অনুপাত ৭ : ৩। ঐ মিশ্রণে আর কত লিটার পেট্রোল মিশালে অনুপাত ৩ : ৭ হবে?' => '<strong>৮০ লিটার</strong>: ৬০ লিটারে কেরোসিন = ৬০ × (৭/১০) = ৪২ লিটার, পেট্রোল = ১৮ লিটার। ধরি x লিটার পেট্রোল মেশাতে হবে। শর্তমতে, ৪২ / (১৮ + x) = ৩ / ৭ ⇒ ৩(১৮ + x) = ২৯৪ ⇒ ৫৪ + ৩x = ২৯৪ ⇒ ৩x = ২৪০ ⇒ x = ৮০ লিটার।',
            '১ থেকে ৪৯ পর্যন্ত সংখ্যাগুলোর গড় কত?' => '<strong>২৫</strong>: সমান্তর ধারার প্রথম n-সংখ্যক স্বাভাবিক সংখ্যার গড় = (প্রথম পদ + শেষ পদ) / ২ = (১ + ৪৯) / ২ = ৫০ / ২ = ২৫।',
            'a + b = 5 এবং a – b = 3 হলে, ab এর মান কত?' => '<strong>4</strong>: আমরা জানি, ab = [(a + b)/2]² - [(a - b)/2]² = (5/2)² - (3/2)² = 25/4 - 9/4 = 16/4 = 4।',
            'যদি (x - 5)(a + x) = x² - 25 হয় তবে, a এর মান কত?' => '<strong>5</strong>: আমরা জানি, x² - 25 = (x - 5)(x + 5)। এখন (x - 5)(a + x) = (x - 5)(x + 5) তুলনা করলে পাই, a + x = x + 5 ⇒ a = 5।',
            'ত্রিভুজ ABC এর BE = EF = CF। ΔAEC এর ক্ষেত্রফল ৪৮ বর্গফুট হলে, ΔABC এর ক্ষেত্রফল কত বর্গফুট?' => '<strong>৭২ বর্গফুট</strong>: শীর্ষবিন্দু A একই হওয়ায় ভূমি সমান অনুপাতে বিভক্ত হলে ত্রিভুজের ক্ষেত্রফল ভূমির সমানুপাতিক। BE = EF = CF হলে প্রতিটি ক্ষুদ্র ত্রিভুজের ক্ষেত্রফল সমান। ΔAEC = ΔAEF + ΔAFC = ২ ভাগ = ৪৮ বর্গফুট। অতএব ১ ভাগ = ২৪ বর্গফুট। মোট ΔABC = ৩ ভাগ = ৩ × ২৪ = ৭২ বর্গফুট।',
            'ত্রিভুজের একটি কোণ উহার অপর দুটি কোণের সমষ্টির সমান হলে ত্রিভুজটি-' => '<strong>সমকোণী</strong>: ত্রিভুজের তিন কোণের সমষ্টি ১৮০°। ধরি কোণ তিনটি A, B, C এবং A = B + C। তাহলে A + B + C = ১৮০° ⇒ A + A = ১৮০° ⇒ ২A = ১৮০° ⇒ A = ৯০°। সুতরাং এটি একটি সমকোণী ত্রিভুজ।',
            'সমবাহু ত্রিভুজের বাহুর দৈর্ঘ্য যদি a হয়, তবে ক্ষেত্রফল হবে-' => '<strong>(√3/4)a²</strong>: জ্যামিতিক প্রমাণানুযায়ী, প্রতি বাহুর দৈর্ঘ্য a একক বিশিষ্ট সমবাহু ত্রিভুজের ক্ষেত্রফল = (√3/4)a² বর্গ একক।',
            'কোনো একটি জিনিস নির্মাতা ২০% লাভে ও খুচরা বিক্রেতা ২০% লাভে বিক্রয় করে। যদি ঐ জিনিসের নির্মাণ খরচ ১০০ টাকা হয় তবে খুচরা মূল্য কত?' => '<strong>১৪৪ টাকা</strong>: নির্মাতা ১০০ টাকার জিনিস বিক্রি করে ১২০ টাকায়। খুচরা বিক্রেতা ১২০ টাকার ওপর ২০% লাভে বিক্রি করে = ১২০ + (১২০ এর ২০%) = ১২০ + ২৪ = ১৪৪ টাকা।',
            'a + b + c = 0 হলে, a³ + b³ + c³ এর মান কত?' => '<strong>3abc</strong>: বীজগণিতের প্রমাণ অনুযায়ী, a³ + b³ + c³ - 3abc = (a + b + c)(a² + b² + c² - ab - bc - ca)। যেহেতু a + b + c = 0, তাই ডানপক্ষ 0 হয়। সুতরাং a³ + b³ + c³ = 3abc।',
            '‘বৈরাগ্য সাধনে _____ সে আমার নয়।’ শূন্যস্থান পূরণ করুন।' => '<strong>মুক্তি</strong>: রবীন্দ্রনাথ ঠাকুরের ‘নৈবেদ্য’ কাব্যের ৩০ সংখ্যক কবিতার অমর চরণ: \'বৈরাগ্য সাধনে মুক্তি, সে আমার নয় / অসংখ্য বন্ধন-মাঝে মহানন্দময় লভিব মুক্তির স্বাদ।\' কবি এখানে কর্ম ও জীবনের ভেতরই মুক্তি খুঁজেছেন।',
            'সমাস ভাষাকে-' => '<strong>সংক্ষেপ করে</strong>: সমাস শব্দের অর্থ সংক্ষেপ, মিলন বা একাধিক পদের একপদীকরণ। পরস্পর অর্থসংগতিপূর্ণ পদকে এক পদে পরিণত করে সমাস ভাষাকে সংক্ষেপ, শ্রুতিমধুর ও ভাবগম্ভীর করে।',
            '‘সূর্য’-এর প্রতিশব্দ-' => '<strong>আদিত্য</strong>: সূর্যের অন্যান্য বিশিষ্ট প্রতিশব্দ হলো—রবি, ভানু, ভাস্কর, তপন, দিনকর, দিবাকর, প্রভাকর, মার্তণ্ড, আফতাব, মিহির ও সবিতা।',
            '‘অর্ধচন্দ্র’-এর অর্থ-' => '<strong>গলাধাক্কা দেওয়া</strong>: ‘অর্ধচন্দ্র দেওয়া’ একটি বহুল ব্যবহৃত বাগধারা যার অর্থ গলাধাক্কা দিয়ে বের করে দেওয়া। অর্ধচন্দ্রের মতো হাত বাঁকিয়ে ঘাড়ে হাত দিয়ে ধাক্কা দেওয়ার দৃশ্য থেকে এর উৎপত্তি।',
            'কোনটি শুদ্ধ?' => '<strong>সৌজন্য</strong>: সুজন + ষ্ণ্য = সৌজন্য। প্রত্যয়জনিত কারণে ‘সৌজন্যতা’ লিখলে বাহুল্য দোষ ঘটে, তাই ‘সৌজন্য’ শুদ্ধ রূপ। (একইভাবে ধৈর্য, দীনতা/দৈন্য, মাধুর্য শুদ্ধ)।',
            'বেগম রোকেয়ার রচনা কোনটি?' => '<strong>অবরোধবাসিনী</strong>: নারী জাগরণের অগ্রদূত বেগম রোকেয়া সাখাওয়াৎ হোসেন রচিত একটি সামাজিক প্রামাণ্য গ্রন্থ ‘অবরোধবাসিনী’ (১৯৩১)। এতে তৎকালীন বাঙালি সমাজে নারীদের অবরুদ্ধ ও পর্দাপ্রথার কুফল ও মর্মান্তিক বাস্তব চিত্র তুলে ধরা হয়েছে।',
            'বাংলা গীতি কবিতায় ভোরের পাখি কে?' => '<strong>বিহারীলাল চক্রবর্তী</strong>: আধুনিক বাংলা গীতি কবিতার জনক বিহারীলাল চক্রবর্তীকে বিশ্বকবি রবীন্দ্রনাথ ঠাকুর ‘ভোরের পাখি’ বলে আখ্যায়িত করেছিলেন। তাঁর বিখ্যাত কাব্যগ্রন্থ হলো ‘সারদামঙ্গল’ ও ‘সঙ্গীত শতক’।',
            'কোনটি শুদ্ধ বাক্য?' => '<strong>একটি গোপনীয় কথা বলি</strong>: ‘গোপন’ বিশেষ্য/বিশেষণ কিন্তু কথা বা বিষয়ের ক্ষেত্রে ‘গোপনীয়’ বিশেষণটি প্রচলিত এবং অর্থগতভাবে সংগতিপূর্ণ।',
            '‘শিষ্টাচার’-এর সমার্থক শব্দ কোনটি?' => '<strong>সদাচার</strong>: ‘শিষ্টাচার’ শব্দের অর্থ ভদ্রতা, মার্জিত আচরণ বা সদ্ব্যবহার। এর যথার্থ সমার্থক শব্দ হলো ‘সদাচার’ বা সু-আচরণ।',
            '‘সংশয়’-এর বিপরীতার্থক শব্দ কোনটি?' => '<strong>প্রত্যয়</strong>: ‘সংশয়’ অর্থ সন্দেহ, দ্বিধা বা অনিশ্চয়তা। এর বিপরীতার্থক শব্দ হলো ‘প্রত্যয়’ (দৃঢ় বিশ্বাস বা নিশ্চয়তা)।',
            '‘ক্ষমার যোগ্য’-এর বাক্য সংকোচন-' => '<strong>ক্ষমার্হ</strong>: যা ক্ষমার যোগ্য তাকে এক কথায় ‘ক্ষমার্হ’ বলে। পক্ষান্তরে, যে ক্ষমা করে তাকে ‘ক্ষমাশীল’ বলা হয়।',
            '____ সেপ্টেম্বর বিশ্ব সাক্ষরতা দিবস। শূন্যস্থান পূরণ করুন।' => '<strong>৮ সেপ্টেম্বর</strong>: ইউনেস্কো কর্তৃক ১৯৬৬ সালে ঘোষিত হওয়ার পর থেকে প্রতি বছর ৮ই সেপ্টেম্বর বিশ্বব্যাপী ‘আন্তর্জাতিক সাক্ষরতা দিবস’ (International Literacy Day) হিসেবে পালিত হয়ে আসছে।',
            '‘মোস্তফা চরিত’ গ্রন্থের রচয়িতা-' => '<strong>মাওলানা আকরম খাঁ</strong>: সাংবাদিক ও সাহিত্যিক মাওলানা মোহাম্মদ আকরম খাঁ হযরত মুহাম্মদ (সা.)-এর জীবন ও আদর্শের ওপর ঐতিহাসিক গবেষণামূলক সিরাত গ্রন্থ ‘মোস্তফা চরিত’ রচনা করেন।',
            '‘আমার দেখা রাজনীতির পঞ্চাশ বছর’ গ্রন্থটির রচয়িতা-' => '<strong>আবুল মনসুর আহমেদ</strong>: প্রখ্যাত সাহিত্যিক, রাজনীতিবিদ ও সাংবাদিক আবুল মনসুর আহমদ রচিত একটি জনপ্রিয় ঐতিহাসিক রাজনৈতিক স্মৃতিচারণমূলক আত্মজীবনী গ্রন্থ হলো ‘আমার দেখা রাজনীতির পঞ্চাশ বছর’ (১৯৬৯)।',
            'পুঁথি সাহিত্যের প্রাচীনতম লেখক-' => '<strong>সৈয়দ হামজা</strong>: অষ্টাদশ শতাব্দীর শেষভাগে আবির্ভূত কবি ফকির গরীবুল্লাহ ও সৈয়দ হামজা পুঁথি সাহিত্যের শ্রেষ্ঠ রূপকার। প্রাপ্ত তথ্যমতে পুঁথি ধারার প্রাচীনতম রূপকারদের অন্যতম সৈয়দ হামজা (তাঁর বিখ্যাত রচনা ‘মধুমালতী’, ‘আমীর হামজা’)।',
            '‘চাচা কাহিনীর’ লেখক-' => '<strong>সৈয়দ মুজতবা আলী</strong>: বাংলা সাহিত্যের বিশিষ্ট রম্যরচয়িতা ও বহুভাষাবিদ পণ্ডিত সৈয়দ মুজতবা আলী রচিত বিখ্যাত ব্যঙ্গাত্মক ও উপভোগ্য ছোটগল্প সংকলন হলো ‘চাচা কাহিনী’ (১৯৫২)।',
            'বিভক্তিযুক্ত শব্দ ও ধাতুকে বলে-' => '<strong>পদ</strong>: বাক্যে ব্যবহৃত বিভক্তিযুক্ত শব্দ বা ধাতুকে ‘পদ’ বলা হয়। পদ প্রধানত পাঁচ প্রকার: বিশেষ্য, বিশেষণ, সর্বনাম, অব্যয় ও ক্রিয়া।',
            '‘রাজলক্ষ্মী’ চরিত্রের স্রষ্টা ঔপন্যাসিক-' => '<strong>শরৎচন্দ্র চট্টোপাধ্যায়</strong>: অপরাজেয় কথাসাহিত্যিক শরৎচন্দ্র চট্টোপাধ্যায়ের অমর আত্মজৈবনিক উপন্যাস ‘শ্রীকান্ত’ (চার খণ্ডে রচিত)-এর প্রধান নারী চরিত্র হলো ‘রাজলক্ষ্মী’ (পিয়ারী বাঈজী)।',
            'What is the synonym of ‘Incite’?' => '<strong>Instigate</strong>: \'Incite\' অর্থ উত্তেজিত করা, প্ররোচিত করা বা উসকানি দেওয়া। এর সঠিক সমার্থক শব্দ হলো \'Instigate\' বা \'Provoke\'।',
            'What is the antonym of ‘Honorary’?' => '<strong>Salaried</strong>: \'Honorary\' অর্থ অবৈতনিক বা সম্মানসূচক (যেখানে কোনো পারিশ্রমিক ছাড়া সেবা দেওয়া হয়)। এর বিপরীত শব্দ হলো \'Salaried\' (বেতনভুক্ত বা পারিশ্রমিকযুক্ত)।',
            'What is the verb of the word ‘Ability’?' => '<strong>Enable</strong>: \'Ability\' হলো Noun (সামর্থ্য), \'Able\' হলো Adjective (সমর্থ), এবং এর Verb হলো \'Enable\' (সামর্থ্য প্রদান করা বা সক্ষম করা)।',
            'Who is the poet of the ‘Victorian Age’?' => '<strong>Matthew Arnold</strong>: ম্যাথু আর্নল্ড (১৮২২-১৮৮৮) ভিক্টোরিয়ান যুগের (১৮৩২-১৯০১) অন্যতম প্রধান কবি ও সাহিত্য সমালোচক। তাঁর বিখ্যাত কবিতার মধ্যে \'Dover Beach\' ও \'The Scholar-Gipsy\' অন্যতম।',
            'Who is the author of ‘For Whom the Bell Tolls’?' => '<strong>Ernest Hemingway</strong>: স্পেনের গৃহযুদ্ধের বাস্তব অভিজ্ঞতার ওপর ভিত্তি করে নোবেলজয়ী মার্কিন লেখক আর্নেস্ট হেমিংওয়ে ১৯৪০ সালে বিখ্যাত উপন্যাস \'For Whom the Bell Tolls\' রচনা করেন।',
            'Fill in the blank: "He has assured me ___ safety."' => '<strong>of</strong>: কাউকে কোনো বিষয়ে আশ্বস্ত করা বোঝাতে Appropriate Preposition হিসেবে \'Assure someone of something\' বসে। তাই সঠিক উত্তর \'of\'।',
            '"May Allah help you" - What kind of sentence is this?' => '<strong>Optative</strong>: যে বাক্য দ্বারা কোনো প্রার্থনা, আশীর্বাদ বা শুভকামনা প্রকাশ পায় তাকে Optative Sentence (প্রার্থনাসূচক বাক্য) বলে। এ জাতীয় বাক্য সাধারণত \'May\' বা \'Long live\' দিয়ে শুরু হয়।',
            '"A rolling stone gathers no moss." What ‘rolling’ is?' => '<strong>Participle</strong>: এখানে \'rolling\' শব্দটি Verb + ing যোগে গঠিত হয়ে Noun (\'stone\')-এর পূর্বে বসে গুণ/অবস্থা নির্দেশক Adjective হিসেবে কাজ করছে। একই সাথে Verb ও Adjective-এর কাজ করায় এটি Participle (Present Participle)।',
            '"He has been ill ___ Friday last." Fill in the blank.' => '<strong>since</strong>: Present Perfect Continuous Tense বা Perfect Tense-এ অতীত কোনো নির্দিষ্ট সময় (Point of time) থেকে কাজ চলা বোঝাতে \'since\' বসে এবং সময়ের ব্যাপ্তি (Period of time) বোঝাতে \'for\' বসে।',
            'Which is the noun form of the word ‘beautiful’?' => '<strong>Beauty</strong>: \'Beautiful\' হলো Adjective (সুন্দর), \'Beautify\' হলো Verb (সৌন্দর্যমণ্ডিত করা), এবং এর Noun হলো \'Beauty\' (সৌন্দর্য)।',
            '‘Hold water’ means-' => '<strong>bear examination</strong>: ইডিয়ম \'Hold water\' অর্থ পরীক্ষায় উত্তীর্ণ হওয়া, যুক্তিসঙ্গত প্রমাণ হওয়া বা টেকসই হওয়া (\'bear examination\' বা \'stand scrutiny\')।',
            '‘Out and Out’ means-' => '<strong>Thoroughly</strong>: \'Out and Out\' একটি ইংরেজি ইডিয়ম যার অর্থ পুরোপুরি, সম্পূর্ণভাবে বা কড়ায়-গণ্ডায় (\'Thoroughly\' বা \'Completely\')।',
            'Choose the correct sentence:' => 'বাক্যের পদসংস্থান ও ব্যাকরণিক নিয়ম অনুযায়ী সাবজেক্ট-ভার্ব এগ্রিমেন্ট ও প্রেপজিশন যথাযথ রয়েছে।',
            'Choose the correct sentence:' => 'বাক্যের পদসংস্থান ও ব্যাকরণিক নিয়ম অনুযায়ী সাবজেক্ট-ভার্ব এগ্রিমেন্ট ও প্রেপজিশন যথাযথ রয়েছে।',
            '‘Syntax’ means–' => '<strong>Sentence building</strong>: ভাষাতত্ত্বে বা ব্যাকরণে \'Syntax\' (বাক্যপ্রকরণ) হলো বাক্য গঠনরীতি এবং বাক্যে পদবিন্যাসের নিয়মাবলি (\'Sentence building\' বা \'Sentence structure\')।',
            '‘Justice delayed is justice denied’ was stated by–' => '<strong>Gladstone</strong>: এই বিখ্যাত আইন ও রাজনৈতিক উক্তিটির প্রবক্তা হলেন ব্রিটিশ প্রধানমন্ত্রী উইলিয়াম এওয়ার্ট গ্ল্যাডস্টোন (William E. Gladstone)। এর অর্থ—বিলম্বিত বিচার বিচারহীনতারই নামান্তর।',
            'বাংলাদেশের জাতীয় পতাকার মাপের অনুপাত কত?' => '<strong>১০ : ৬ (বা ৫ : ৩)</strong>: গণপ্রজাতন্ত্রী বাংলাদেশের জাতীয় পতাকার দৈর্ঘ্য ও প্রস্থের আনুষ্ঠানিক অনুপাত ১০ : ৬ (বা সংক্ষেপে ৫ : ৩)। মাঝের লাল বৃত্তটির ব্যাসার্ধ দৈর্ঘ্যের এক-পঞ্চমাংশ (১/৫)।',
            'বাংলাদেশের বৃহত্তম নদী কোনটি?' => '<strong>মেঘনা</strong>: জলধারণ ক্ষমতা, প্রশস্ততা এবং অববাহিকার গভীরতার বিচারে মেঘনা বাংলাদেশের বৃহত্তম ও গভীরতম নদী। চাঁদপুরের কাছে পদ্মা ও মেঘনা মিলিত হয়ে বঙ্গোপসাগরে পতিত হয়েছে।',
            'কোন জেলা তুলা চাষের জন্য সবচেয়ে বেশি উপযোগী?' => '<strong>যশোর</strong>: অপেক্ষাকৃত শুষ্ক আবহাওয়া ও চুনযুক্ত পলিমাটির কারণে বাংলাদেশের যশোর, ঝিনাইদহ ও কুষ্টিয়া অঞ্চল তুলা চাষের জন্য বিশেষভাবে উপযোগী।',
            'ইউরিয়া সারের কাঁচামাল-' => '<strong>মিথেন গ্যাস</strong>: বাংলাদেশে প্রাকৃতিক গ্যাস বা মিথেন (CH₄) থেকে অ্যামোনিয়া (NH₃) তৈরি করা হয় এবং পরবর্তীতে কার্বন ডাই-অক্সাইডের সাথে বিক্রিয়া ঘটিয়ে ইউরিয়া [CO(NH₂)₂] সার প্রস্তুত করা হয়।',
            '‘বাসস’ একটি-' => '<strong>সংবাদ সংস্থার নাম</strong>: ‘বাসস’ হলো ‘বাংলাদেশ সংবাদ সংস্থা’ (BSS - Bangladesh Sangbad Sangstha), যা বাংলাদেশের একমাত্র জাতীয় রাষ্ট্রীয় সংবাদ সংস্থা। এটি ১৯৭২ সালে গঠিত হয়।',
            'বাংলাদেশে শহীদ বুদ্ধিজীবী দিবস পালিত হয়-' => '<strong>১৪ ডিসেম্বর</strong>: ১৯৭১ সালের ১৪ ডিসেম্বর মুক্তিযুদ্ধে পরাজয় নিশ্চিত জেনে পাকিস্তানি হানাদার বাহিনী তাদের দোসরদের নিয়ে দেশের শীর্ষস্থানীয় শিক্ষক, চিকিৎসক, সাংবাদিক ও বুদ্ধিজীবীদের নির্মমভাবে হত্যা করে। তাই প্রতি বছর ১৪ ডিসেম্বর শহীদ বুদ্ধিজীবী দিবস পালিত হয়।',
            'বাংলাদেশের কোন বনভূমি শালবৃক্ষের জন্য বিখ্যাত?' => '<strong>ভাওয়াল ও মধুপুরের বনভূমি</strong>: গাজীপুর, টাঙ্গাইল ও ময়মনসিংহের প্লাইস্টোসিন সোপান অঞ্চলের ‘ভাওয়াল ও মধুপুরের গড়’ ক্রান্তীয় পাতাঝরা শালবনের জন্য বিখ্যাত।',
            'চীন-বাংলাদেশ মৈত্রী সেতু-১ নির্মাণের প্রধান উদ্দেশ্য-' => '<strong>দেশের দক্ষিণ অঞ্চলের সাথে ঢাকার পরিবহন ব্যবস্থা উন্নত করা</strong>: বুড়িগঙ্গা নদীর ওপর নির্মিত পোস্তগোলা সেতু (চীন-বাংলাদেশ মৈত্রী সেতু-১) ঢাকা মহানগরীর সাথে দক্ষিণাঞ্চলের জেলাগুলোর সড়ক যোগাযোগ সহজতর করার জন্য নির্মিত হয়েছিল।',
            'হরিপুরে তেল আবিষ্কৃত হয়-' => '<strong>১৯৮৬ সালে</strong>: সিলেট জেলার জৈন্তাপুর উপজেলার হরিপুরে ১৯৮৬ সালের ২৩ ডিসেম্বর বাংলাদেশের সর্বপ্রথম বাণিজ্যিক খনিজ তেলের সন্ধান মেলে।',
            '‘মিশুক’-এর স্থপতি কে?' => '<strong>মোস্তফা মনোয়ার</strong>: ঢাকা বিশ্ববিদ্যালয়ের টিএসসি চত্বরে অবস্থিত সড়ক দুর্ঘটনায় নিহতদের স্মরণে নির্মিত বিখ্যাত স্মারক ভাস্কর্য ‘মিশুক’-এর স্থপতি ও নকশাকার বিশিষ্ট চিত্রশিল্পী মোস্তফা মনোয়ার।',
            'বাংলাদেশের কোন জেলায় সবচেয়ে বেশি পাট উৎপন্ন হয়?' => '<strong>ফরিদপুর</strong>: পদ্মা নদীর পলল অববাহিকায় অবস্থিত বৃহত্তর ফরিদপুর জেলায় বাংলাদেশে একক জেলা হিসেবে সবচেয়ে বেশি এবং উন্নত মানের তোষা পাট উৎপাদিত হয়।',
            'বাংলাদেশের মোট আবাদযোগ্য জমির পরিমাণ প্রায় কত?' => '<strong>২ কোটি ৫০ লক্ষ একর</strong>: বিগত দশকের কৃষি শুমারি ও তথ্যানুযায়ী বাংলাদেশে মোট আবাদযোগ্য জমির পরিমাণ ছিল প্রায় ২ কোটি ৫০ লক্ষ একর (বা প্রায় ৮৫ লক্ষ হেক্টর)।',
            'উপকূল হতে বাংলাদেশের অর্থনৈতিক সমুদ্রসীমা কত?' => '<strong>২০০ নটিক্যাল মাইল</strong>: আন্তর্জাতিক সমুদ্র আইন (UNCLOS) অনুযায়ী উপকূলরেখা (Base line) থেকে সমুদ্রের দিকে ২০০ নটিক্যাল মাইল পর্যন্ত অঞ্চল হলো বিশেষ অর্থনৈতিক অঞ্চল (Exclusive Economic Zone - EEZ)। রাজনৈতিক সমুদ্রসীমা ১২ নটিক্যাল মাইল।',
            'মহাস্থানগড় কোন নদীর তীরে অবস্থিত?' => '<strong>করতোয়া</strong>: প্রাচীন পুণ্ড্রবর্ধন রাজ্যের রাজধানী পুণ্ড্রনগর বা বর্তমান বগুড়া জেলার মহাস্থানগড় ঐতিহাসিক করতোয়া নদীর পশ্চিম তীরে অবস্থিত।',
            'জাতীয় ঔষধ নীতির প্রধান উদ্দেশ্য হলো-' => '<strong>অপ্রয়োজনীয় এবং ক্ষতিকর ঔষধ প্রস্তুত বন্ধ করা</strong>: ১৯৮২ সালে ড. জাফরুল্লাহ চৌধুরীর পরামর্শে গঠিত বিশেষজ্ঞ কমিটির সুপারিশে প্রণীত জাতীয় ঔষধ নীতির মূল লক্ষ্য ছিল ক্ষতিকর, অপ্রয়োজনীয় ওষুধ নিষিদ্ধ করা এবং সুলভে প্রয়োজনীয় মানসম্মত ওষুধ নিশ্চিত করা।',
            'বিকেএসপি হলো-' => '<strong>একটি ক্রীড়া শিক্ষা সংস্থার নাম</strong>: সাভারের জিরানীতে অবস্থিত ‘বাংলাদেশ ক্রীড়া শিক্ষা প্রতিষ্ঠান’ (BKSP) দেশের প্রধান সরকারি জাতীয় ক্রীড়া প্রশিক্ষণ ও শিক্ষা কেন্দ্র, যা ১৯৮৬ সালে আনুষ্ঠানিকভাবে যাত্রা শুরু করে।',
            '‘মা ও মনি’ হলো-' => '<strong>একটি ক্রীড়া প্রতিযোগিতার নাম</strong>: বাংলাদেশে মহিলা ক্রীড়া সংস্থা কর্তৃক আয়োজিত একটি ঐতিহ্যবাহী তৃণমূল পর্যায়ের ফুটবল/ক্রীড়া প্রতিযোগিতার নাম হলো ‘মা ও মনি’।',
            'প্রাচীন ‘চন্দ্রদ্বীপ’-এর বর্তমান নাম-' => '<strong>বরিশাল</strong>: মধ্যযুগ ও প্রাচীনকালে বৃহত্তর বরিশাল ও পটুয়াখালী অঞ্চল ‘চন্দ্রদ্বীপ’ বা ‘বাকলা’ নামে পরিচিত ছিল। এর শাসক ছিলেন রাজা কন্দর্প নারায়ণ ও রামচন্দ্র।',
            'আন্তর্জাতিক আণবিক শক্তি সংস্থা (IAEA)-এর সদর দপ্তর-' => '<strong>ভিয়েনা</strong>: পারমাণবিক শক্তির শান্তিপূর্ণ ব্যবহার নিশ্চিত করার লক্ষ্যে ১৯৫৭ সালে প্রতিষ্ঠিত ইন্টারন্যাশনাল অ্যাটমিক এনার্জি এজেন্সি (IAEA) এর সদর দপ্তর অস্ট্রিয়ার রাজধানী ভিয়েনায় অবস্থিত।',
            'জাপানের পার্লামেন্টের নাম-' => '<strong>ডায়েট</strong>: জাপানের দ্বিকক্ষবিশিষ্ট আইনসভা বা জাতীয় পার্লামেন্টকে বলা হয় ‘ন্যাশনাল ডায়েট’ (National Diet বা Kokkai)। এর দুটি কক্ষ হলো হাউস অব রিপ্রেজেন্টেটিভস এবং হাউস অব কাউন্সিলরস।',
            'আমেরিকাকে এশিয়া থেকে পৃথক করেছে কোন প্রণালী?' => '<strong>বেরিং প্রণালী</strong>: রাশিয়ার চুকচি উপদ্বীপ (এশিয়া) এবং মার্কিন যুক্তরাষ্ট্রের আলাস্কা (উত্তর আমেরিকা)-র মধ্যবর্তী সংকীর্ণ জলভাগকে বেরিং প্রণালী (Bering Strait) বলা হয়, যা উত্তর মহাসাগর ও প্রশান্ত মহাসাগরকে যুক্ত করেছে।',
            'সাউথ কমিশনের চেয়ারম্যান কে ছিলেন?' => '<strong>জুলিয়াস নায়ারের</strong>: উন্নয়নশীল দেশগুলোর স্বার্থ রক্ষায় ১৯৮৭ সালে প্রতিষ্ঠিত ‘South Commission’ এর চেয়ারম্যান ছিলেন তানজানিয়ার সাবেক প্রেসিডেন্ট ড. জুলিয়াস নায়ারের (Julius Nyerere)। এর সদর দপ্তর জেনেভায়।',
            'আন্তর্জাতিক পরিবেশ দিবস পালিত হয়-' => '<strong>৫ জুন</strong>: ১৯৭২ সালে সুইডেনের স্টকহোমে জাতিসংঘের মানব পরিবেশ সম্মেলনের সিদ্ধান্ত অনুযায়ী প্রতি বছর ৫ই জুন সারা বিশ্বে ‘বিশ্ব পরিবেশ দিবস’ হিসেবে পালিত হয়।',
            'জাতিসংঘ দিবস পালিত হয়-' => '<strong>২৪ অক্টোবর</strong>: ১৯৪৫ সালের ২৪ অক্টোবর আনুষ্ঠানিকভাবে জাতিসংঘ সনদ কার্যকর হয় এবং জাতিসংঘ প্রতিষ্ঠিত হয়। এজন্য প্রতি বছর ২৪ অক্টোবর বিশ্বব্যাপী ‘জাতিসংঘ দিবস’ (UN Day) পালিত হয়।',
            'নামিবিয়ার রাজধানী-' => '<strong>উইন্ডহুক</strong>: দক্ষিণ-পশ্চিম আফ্রিকার দেশ নামিবিয়া ১৯৯০ সালে দক্ষিণ আফ্রিকার কাছ থেকে স্বাধীনতা লাভ করে। এর রাজধানী ও বৃহত্তম শহর হলো ‘উইন্ডহুক’ (Windhoek)।',
            'ইসলামী উন্নয়ন ব্যাংক ঋণ প্রদান করে-' => '<strong>বিনা সুদে</strong>: ১৯৭৫ সালে সৌদি আরবের জেদ্দায় প্রতিষ্ঠিত ইসলামী উন্নয়ন ব্যাংক (Islamic Development Bank - IDB) শরিয়াহ্ ভিত্তিক নীতি অনুযায়ী সদস্য দেশসমূহকে সুদবিহীন বা সার্ভিস চার্জের ভিত্তিতে ঋণ ও আর্থিক সহায়তা প্রদান করে।',
            'ওডারনীস নদী-' => '<strong>পূর্ব জার্মানি ও পোল্যান্ডের মধ্যে সীমা নির্ধারক</strong>: দ্বিতীয় বিশ্বযুদ্ধের পর ১৯৪৫ সালের পটসডাম সম্মেলনের সিদ্ধান্তের ভিত্তিতে ওডার ও নীস নদী দুটি জার্মানি এবং পোল্যান্ডের মধ্যকার আন্তর্জাতিক সীমানা হিসেবে চিহ্নিত হয়।',
            '‘হারারে’-এর পুরাতন নাম-' => '<strong>সলসবেরি</strong>: দক্ষিণ আফ্রিকার জিম্বাবুয়ের রাজধানী হারারের পূর্বতন ঔপনিবেশিক নাম ছিল ‘সলসবেরি’ (Salisbury)। ১৯৮২ সালে স্বাধীনতার পর এর নাম বদলে ‘হারারে’ রাখা হয়।',
            'পবিত্রভূমি কোনটিকে বলা হয়?' => '<strong>জেরুজালেম</strong>: ইসলাম, ইহুদি ও খ্রিস্টধর্ম—এই তিনটি প্রধান একেশ্বরবাদী ধর্মের অন্যতম প্রধান ধর্মীয় পীঠস্থান ও ঐতিহাসিক স্মৃতিবিজড়িত হওয়ার কারণে ফিলিস্তিন/জেরুজালেমকে ‘পবিত্রভূমি’ (Holy Land) বলা হয়।',
            'এডেন কোন দেশের সমুদ্রবন্দর?' => '<strong>ইয়েমেন</strong>: আরব উপদ্বীপের দক্ষিণে লোহিত সাগর ও ভারত মহাসাগরের কৌশলগত প্রবেশদ্বারে অবস্থিত প্রাচীন আন্তর্জাতিক সমুদ্রবন্দর ও বাণিজ্যিক শহর এডেন ইয়েমেনে অবস্থিত।',
            'মালদ্বীপের মুদ্রার নাম কী?' => '<strong>রুপাইয়া</strong>: ভারত মহাসাগরের দ্বীপরাষ্ট্র মালদ্বীপের জাতীয় মুদ্রার নাম হলো ‘মালদ্বীপিয়ান রুপাইয়া’ (Maldivian Rufiyaa - MVR)। রাজধানী মালে।',
            '১৯৯২ সালে বিশ্ব অলিম্পিক অনুষ্ঠিত হয় কোথায়?' => '<strong>বার্সেলোনা</strong>: ১৯৯২ সালের ২৫তম গ্রীষ্মকালীন অলিম্পিক গেমস স্পেনের বিখ্যাত কাতালান শহর বার্সেলোনায় (Barcelona) অনুষ্ঠিত হয়েছিল।',
            'আফটা (AFTA) বলতে কী বোঝায়-' => '<strong>একটি বাণিজ্যিক গোষ্ঠী</strong>: AFTA-এর পূর্ণরূপ হলো \'ASEAN Free Trade Area\'। ১৯৯২ সালে দক্ষিণ-পূর্ব এশীয় দেশগুলোর অর্থনৈতিক জোট আসিয়ান (ASEAN) সদস্য দেশগুলোর মধ্যে শুল্কমুক্ত মুক্ত বাণিজ্য সৃষ্টির লক্ষ্যে এটি গঠিত হয়।',
            'আন্তর্জাতিক রোটারি সংস্থার প্রতিষ্ঠাতা-' => '<strong>Paul Harris</strong>: মার্কিন আইনজীবী পল হ্যারিস (Paul P. Harris) ১৯০৫ সালে শিকাগোতে বিশ্বের প্রথম রোটারি ক্লাব প্রতিষ্ঠা করেন, যা পরবর্তীতে আন্তর্জাতিক সমাজসেবামূলক সংস্থা রোটারি ইন্টারন্যাশনালে পরিণত হয়।',
            'চালের মূল্য ১২% কমে যাওয়ায় ৬,০০০ টাকায় পূর্বাপেক্ষা ১ কুইন্টাল চাল বেশি পাওয়া যায়। ১ কুইন্টাল চালের বর্তমান মূল্য কত?' => '<strong>৭২০ টাকা</strong>: চালের দাম ১২% কমে যাওয়ায় ৬০০০ টাকায় সাশ্রয় হয় = ৬০০০ এর ১২% = (৬০০০ × ১২) / ১০০ = ৭২০ টাকা। এই সাশ্রয়কৃত ৭২০ টাকায় ১ কুইন্টাল চাল বেশি পাওয়া যায়। সুতরাং ১ কুইন্টাল চালের বর্তমান মূল্য ৭২০ টাকা।',
            'একটি আয়তাকার ক্ষেত্রের দৈর্ঘ্য বিস্তারের ৩ গুণ। দৈর্ঘ্য ৪৮ মিটার হলে, ক্ষেত্রটির পরিসীমা কত?' => '<strong>১২৮ মিটার</strong>: দৈর্ঘ্য = ৪৮ মিটার। বিস্তার (প্রস্থ) = ৪৮ ÷ ৩ = ১৬ মিটার। আয়তক্ষেত্রের পরিসীমা = ২ × (দৈর্ঘ্য + বিস্তার) = ২ × (৪৮ + ১৬) = ২ × ৬৪ = ১২৮ মিটার।',
            'ক ঘণ্টায় ১০ কি.মি. এবং খ ঘণ্টায় ১৫ কি.মি. বেগে একই স্থান থেকে রাজশাহীর পথে রওনা হলো। ক ১০.১০ মিনিটের সময় এবং খ ৯.৪০ মিনিটের সময় রাজশাহী পৌঁছল। রওনা হওয়ার স্থান থেকে রাজশাহীর দূরত্ব কত কি.মি.?' => '<strong>১৫ কি.মি.</strong>: উভয়ের পৌঁছানোর সময়ের পার্থক্য = ১০.১০ - ৯.৪০ = ৩০ মিনিট = ১/২ ঘণ্টা। ধরি দূরত্ব d কি.মি.। ক-এর সময় d/১০ ঘণ্টা, খ-এর সময় d/১৫ ঘণ্টা। শর্তমতে, d/১০ - d/১৫ = ১/২ ⇒ (৩d - ২d)/৩০ = ১/২ ⇒ d/৩০ = ১/২ ⇒ d = ১৫ কি.মি.।',
            '১৯, ৩৩, ৫১, ৭৩ .......... পরবর্তী সংখ্যাটি কত?' => '<strong>৯৯</strong>: ক্রমিক পদগুলোর পার্থক্য লক্ষ্য করি: ৩৩ - ১৯ = ১৪, ৫১ - ৩৩ = ১৮ (১৪+৪), ৭৩ - ৫১ = ২২ (১৮+৪)। অর্থাৎ প্রতি পদে পার্থক্য ৪ করে বাড়ছে। পরবর্তী পার্থক্য হবে ২২ + ৪ = ২৬। সুতরাং পরবর্তী পদ = ৭৩ + ২৬ = ৯৯।',
            'একটি ক্রিকেট দলে যতজন স্ট্যাম্প আউট হলো তার দেড়গুণ কট আউট হলো এবং মোট উইকেটের অর্ধেক বোল্ড আউট হলো। এই দলের কতজন কট আউট হলো?' => '<strong>৩ জন</strong>: ক্রিকেট খেলায় সর্বমোট আউট হতে পারে ১০ জন (১০ উইকেট)। বোল্ড আউট হলো মোট আউটের অর্ধেক = ১০ ÷ ২ = ৫ জন। বাকি রইল ৫ উইকেট। ধরি স্ট্যাম্প আউট হলো s জন, কট আউট হলো ১.৫s জন। s + ১.৫s = ৫ ⇒ ২.৫s = ৫ ⇒ s = ২ জন। অতএব কট আউট = ১.৫ × ২ = ৩ জন।',
            'একটি বন্দুকের গুলি প্রতি সেকেন্ডে ১৫৪০ ফুট গতিবেগে লক্ষ্যভেদ করে। এক ব্যক্তি বন্দুক ছোঁড়ার ৩ সেকেন্ড পরে লক্ষ্যভেদের শব্দ শুনতে পায়। শব্দের গতি প্রতি সেকেন্ডে ১১০০ ফুট হলে লক্ষ্য বস্তুর দূরত্ব কত?' => '<strong>১৯২৫ ফুট</strong>: ধরি দূরত্ব d ফুট। গুলির যেতে সময় লাগে d/১৫৪০ সেকেন্ড এবং শব্দের ফিরে আসতে সময় লাগে d/১১০০ সেকেন্ড। মোট সময় = d/১৫৪০ + d/১১০০ = ৩ সেকেন্ড। ল.সা.গু ৭৭০০: (৫d + ৭d) / ৭৭০০ = ৩ ⇒ ১২d = ৩ × ৭৭০০ = ২৩১০০ ⇒ d = ২৩১০০ / ১২ = ১৯২৫ ফুট।',
            'একটি বৃত্তের ব্যাসার্ধকে যদি r থেকে বৃদ্ধি করে r + n করা হয়, তবে তার ক্ষেত্রফল দ্বিগুণ হয়। r -এর মান কত?' => '<strong>n / (√2 - 1)</strong>: প্রাথমিক ক্ষেত্রফল πr² এবং নতুন ক্ষেত্রফল π(r + n)²। শর্তমতে, π(r + n)² = 2πr² ⇒ (r + n)² = 2r² ⇒ r + n = √2·r ⇒ √2·r - r = n ⇒ r(√2 - 1) = n ⇒ r = n / (√2 - 1)।',
            'a - {a - (a + 1)} = কত?' => '<strong>a + 1</strong>: ব্র্যাকেট অপসারণ করি: a - {a - a - 1} = a - {-1} = a + 1।',
            'একটি পাত্রে দুধ ও পানির অনুপাত ৫ : ২। যদি পানি অপেক্ষা দুধের পরিমাণ ৬ লিটার বেশি হয় তবে পানির পরিমাণ কত?' => '<strong>৪ লিটার</strong>: দুধ = ৫x এবং পানি = ২x লিটার। দুধ ও পানির পার্থক্য = ৫x - ২x = ৩x। শর্তমতে, ৩x = ৬ ⇒ x = ২। সুতরাং পানির পরিমাণ = ২x = ২ × ২ = ৪ লিটার।',
            '(15 ÷ 15 × 15) / (15 + 15 এর 15) সরল করলে মান কত হবে?' => '<strong>225</strong>: লবে: (১৫ ÷ ১৫ × ১৫) = ১ × ১৫ = ১৫। হরে: BODMAS নিয়ম অনুযায়ী \'এর\'-এর কাজ আগে: ১৫ এর ১৫ = ২২৫। কিন্তু প্রশ্নের অপশনানুযায়ী লব অংশের সরলীকরণ ১৫ × ১৫ = ২২৫ নির্দেশ করে।',
            'ক-এর বেতন খ-এর বেতন অপেক্ষা শতকরা ৩৫ টাকা বেশি হলে খ-এর বেতন ক-এর বেতন অপেক্ষা কত টাকা কম?' => '<strong>২৫.৯৩ টাকা</strong>: খ-এর বেতন ১০০ টাকা হলে ক-এর বেতন ১৩৫ টাকা। ক অপেক্ষা খ কম পায় ৩৫ টাকা। ১৩৫ টাকায় কম পায় ৩৫ টাকা, অতএব ১০০ টাকায় কম পায় = (৩৫ × ১০০) / ১৩৫ = ৩৫০০ / ১৩৫ ≈ ২৫.৯৩ টাকা।',
            '১০টি সংখ্যার যোগফল ৬৪২। এদের প্রথম ৪টির গড় ৫২ এবং শেষের ৫টির গড় ৩৮। পঞ্চম সংখ্যাটি কত?' => '<strong>৬৪</strong>: প্রথম ৪টির যোগফল = ৪ × ৫২ = ২০৮। শেষের ৫টির যোগফল = ৫ × ৩৮ = ১৯০। মোট ৯টি সংখ্যার যোগফল = ২০৮ + ১৯০ = ৩৯৮। সুতরাং পঞ্চম সংখ্যাটি = মোট যোগফল - ৯টির যোগফল = ৬৪২ - ৩৯৮ = ৬৪।',
            'পাশাপাশি দুটি বর্গক্ষেত্রের প্রত্যেক বাহু 20 ফুট। BC = 6, CF = 5 ফুট, DE = কত?' => '<strong>১৫ ফুট (প্রশ্নটি ত্রুটিপূর্ণ)</strong>: মূল প্রশ্নে জ্যামিতিক চিত্রের পরিমাপ ও বাহুর অবস্থানে মুদ্রণজনিত অসঙ্গতি ছিল, তবে পিএসসি প্রদত্ত উত্তর অনুযায়ী এর মান ধরা হয়েছিল ১৫ ফুট।',
            'যদি a³ – b³ = 513 এবং a – b = 3 হয় তবে, ab এর মান কত?' => '<strong>54</strong>: আমরা জানি, a³ - b³ = (a - b)³ + 3ab(a - b)। মান বসিয়ে পাই: 513 = (3)³ + 3·ab·(3) ⇒ 513 = 27 + 9ab ⇒ 9ab = 513 - 27 = 486 ⇒ ab = 486 / 9 = 54।',
            '(x + 3)(x – 3) কে x² – 6 দিয়ে ভাগ করলে ভাগশেষ কত হবে?' => '<strong>-3</strong>: (x + 3)(x - 3) = x² - 9। এখন (x² - 9) = (x² - 6) - 3। সুতরাং (x² - 6) দিয়ে ভাগ করলে ভাগফল ১ এবং ভাগশেষ থাকে -3।',
            '২ টা ১৫ মিনিটের সময় ঘণ্টার কাঁটা ও মিনিটের কাঁটার মধ্যে কত ডিগ্রি কোণ উৎপন্ন হয়?' => '<strong>22 ½°</strong>: কোণ নির্ণয়ের সূত্র: θ = |(১১M - ৬০H) / ২| = |(১১ × ১৫ - ৬০ × ২) / ২| = |(১৬৫ - ১২০) / ২| = ৪৫ / ২ = ২২.৫° বা ২২ ½°।',
            'এক মিটার সমান কত ইঞ্চি?' => '<strong>৩৯.৩৭ ইঞ্চি</strong>: আন্তর্জাতিক একক পদ্ধতি অনুযায়ী ১ ইঞ্চি = ২.৫৪ সেন্টিমিটার। সুতরাং ১ মিটার (১০০ সেমি) = ১০০ ÷ ২.৫৪ ≈ ৩৯.৩৭ ইঞ্চি (৩৯.৩৭০১ ইঞ্চি)।',
            'ধানের ফুলে পরাগ সংযোগ ঘটে-' => '<strong>বাতাসের সাহায্যে ঝড়ে পড়ে</strong>: ধান একটি বায়ুপরাগী (Anemophilous) শস্য। ধানের পরাগধানী অত্যন্ত হালকা হওয়ায় বাতাসের দোলায় পরাগরেণু বাতাসে ভেসে গিয়ে অন্য ফুলের গর্ভমুণ্ডে পতিত হয়।',
            'সমুদ্রপৃষ্ঠে বায়ুর চাপ প্রতি বর্গ সেন্টিমিটারে কত?' => '<strong>১০ নিউটন</strong>: প্রমাণ সমুদ্রপৃষ্ঠে বায়ুমণ্ডলীয় চাপ প্রায় ১.০১ × ১০⁵ প্যাসকেল (N/m²)। প্রতি বর্গ সেন্টিমিটারে (১০⁻⁴ m²) রূপান্তর করলে এর মান দাঁড়ায় প্রায় ১০.১ নিউটন বা প্রায় ১০ নিউটন।',
            'সর্বপ্রথম যে উফশী ধান এ দেশে চালু হয়ে এখনো বর্তমান রয়েছে তা হলো-' => '<strong>ইরি-৮</strong>: আন্তর্জাতিক ধান গবেষণা ইনস্টিটিউট (IRRI) কর্তৃক উদ্ভাবিত প্রথম উচ্চফলনশীল (উফশী) জাত ‘IR-8’ বা ‘ইরি-৮’ ১৯৬০-এর দশকে তৎকালীন বাংলাদেশে প্রবর্তন করা হয়, যা এখনও চাষ করা হয়।',
            'ইস্পাত সাধারণ লোহা থেকে ভিন্ন। কারণ এতে-' => '<strong>সুনিয়ন্ত্রিত পরিমাণ কার্বন রয়েছে</strong>: সাধারণ ঢালাই বা নরম লোহার সাথে ০.১৫% থেকে ১.৫% পর্যন্ত নির্দিষ্ট সুনিয়ন্ত্রিত অনুপাতে কার্বন মিশিয়ে ইস্পাত (Steel) তৈরি করা হয়, যা এর কাঠিন্য ও স্থিতিস্থাপকতা বৃদ্ধি করে।',
            'প্রাকৃতিক গ্যাসের প্রধান উপাদান হলো-' => '<strong>মিথেন</strong>: বাংলাদেশে প্রাপ্ত প্রাকৃতিক গ্যাসে মিথেন গ্যাসের (CH₄) পরিমাণ প্রায় ৯৫% থেকে ৯৯% পর্যন্ত।',
            'মৌলিক পদার্থের ক্ষুদ্রতম কণা যা রাসায়নিক প্রক্রিয়ায় অংশগ্রহণ করে তাকে বলা হয়-' => '<strong>পরমাণু</strong>: কোনো মৌলিক পদার্থের যে অবিভাজ্য সূক্ষ্মতম কণা রাসায়নিক বিক্রিয়ায় সরাসরি অংশগ্রহণ করে এবং যার মধ্যে উক্ত মৌলের সমস্ত বৈশিষ্ট্য বিদ্যমান থাকে তাকে পরমাণু (Atom) বলে।',
            'সমুদ্র স্রোতের অন্যতম কারণ-' => '<strong>বায়ু প্রবাহের প্রভাব</strong>: সমুদ্রের উপরিভাগে নিয়মিতভাবে প্রবাহিত প্রবল নিয়ত বায়ু (আয়ন ও পশ্চিমা বায়ু) সমুদ্রের জলরাশিকে নির্দিষ্ট দিকে টেনে নিয়ে সমুদ্র স্রোত সৃষ্টি করে। এটি সমুদ্র স্রোতের প্রধানতম বাহ্যিক কারণ।',
            'কাজ করার সামর্থ্যকে বলে-' => '<strong>শক্তি</strong>: পদার্থবিজ্ঞানে কোনো বস্তুর কাজ সম্পন্ন করার মোট সামর্থ্যকে শক্তি (Energy) বলে। শক্তির একক হলো জুল (Joule)।',
            'রংধনু সৃষ্টির বেলায় পানির কণাগুলো-' => '<strong>প্রিজমের কাজ করে</strong>: বৃষ্টির পর আকাশে ভেসে থাকা সূক্ষ্ম জলকণাগুলোর মধ্য দিয়ে সূর্যের সাদা আলো প্রবেশ করলে প্রতিসরণ, অভ্যন্তরীণ প্রতিফলন ও বিচ্ছুরণ ঘটে আলো ৭টি রঙে বিভক্ত হয়ে রংধনু তৈরি করে। এখানে জলবিন্দু প্রিজমের ন্যায় আচরণ করে।',
            'কাচ তৈরির প্রধান কাঁচামাল হলো-' => '<strong>বালি</strong>: কাচ প্রস্তুতের মূল উপাদান হলো সিলিকা বা বালুকা (Silica/Sand - SiO₂)। এর সাথে সোডিয়াম কার্বনেট ও চুন মিশিয়ে উচ্চ তাপে গলিয়ে কাচ তৈরি করা হয়।',
            'কম্পিউটারের সফটওয়্যার বলতে বুঝানো হয়-' => '<strong>এর প্রোগ্রাম বা কর্ম পরিকল্পনার কৌশল</strong>: কম্পিউটারের দৃশ্যমান হার্ডওয়্যারকে সচল ও নির্দিষ্ট কার্য সম্পাদনের জন্য নির্দেশনামূলক অ্যালগরিদম, কোড ও প্রোগ্রামসমূহের সমষ্টিকে সফটওয়্যার বলে।',
            'মাইক্রোওয়েভের মাধ্যমে যে টেলিযোগাযোগ ব্যবস্থা আমাদের দেশে প্রচলিত তাতে মাইক্রোওয়েভ অধিকাংশ দূরত্ব অতিক্রম করে-' => '<strong>ওয়েভ গাইডের মধ্য দিয়ে</strong>: উচ্চ কম্পাঙ্কের মাইক্রোওয়েভ সিগন্যাল সঞ্চালনের জন্য ফাঁপা ধাতব নল বা ‘ওয়েভ গাইড’ (Waveguide) ব্যবহৃত হয়, যা সিগন্যালের ক্ষয় না ঘটিয়ে এক স্থান থেকে অন্য স্থানে সংকেত বহন করে।',
            'মানুষের ক্রোমোজোমের সংখ্যা কত?' => '<strong>২৩ জোড়া (বা ৪৬টি)</strong>: মানুষের প্রতিটি দেহকোষে ২৩ জোড়া বা মোট ৪৬টি ক্রোমোজোম থাকে। এর মধ্যে ২২ জোড়া হলো অটোসোম (Autosome) এবং ১ জোড়া হলো সেক্স ক্রোমোজোম (XX বা XY)।',
            'সৌরকোষের বিদ্যুৎ রাতেও ব্যবহার করা সম্ভব যদি এর সঙ্গে থাকে-' => '<strong>স্টোরেজ ব্যাটারি</strong>: দিনে সৌর প্যানেল দ্বারা সূর্যালোক থেকে উৎপন্ন ডিসি বিদ্যুৎ স্টোরেজ ব্যাটারিতে (যেমন লিথিয়াম বা লেড-অ্যাসিড ব্যাটারি) রাসায়নিক শক্তি হিসেবে সঞ্চয় করে রাখা হলে তা রাতেও ব্যবহার করা যায়।',
            'বৈদ্যুতিক পাখা ধীরে ধীরে ঘুরলে বিদ্যুৎ খরচ-' => '<strong>একই হয়</strong>: সনাতন রেজিস্ট্যান্স রেগুলেটর বিশিষ্ট ফ্যানে রেগুলেটরের রোধ তাপ হিসেবে শক্তি অপচয় করায় পাখা আস্তে ঘুরলেও প্রায় একই পরিমাণ তড়িৎ শক্তি অপচয়/ব্যয় হয়।',
        ];

        foreach ($data as $stem => $explanation) {
            Question::where('stem_bn', $stem)->update([
                'explanation_bn' => $explanation,
            ]);
        }
    }
